import{_ as a,o,c as t,ag as i}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Host API v1","description":"","frontmatter":{},"headers":[],"relativePath":"spec/host-api/v1.md","filePath":"spec/host-api/v1.md"}'),s={name:"spec/host-api/v1.md"};function n(r,e,d,c,l,p){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="host-api-v1" tabindex="-1">Host API v1 <a class="header-anchor" href="#host-api-v1" aria-label="Permalink to &quot;Host API v1&quot;">​</a></h1><p><code>forms.takoform.com/v1</code> is the stable, provider-neutral Takoform Host API. It installs immutable Form Definitions, accepts desired resources under exact FormRefs, and reports lifecycle state. A passing conformance report is evidence about this contract only; it grants no publication, support, or production readiness status.</p><p>The normative machine documents are:</p><ul><li><a href="operations-v1.json"><code>operations-v1.json</code></a>, the complete route and fence table;</li><li><a href="/schemas/v1/host-discovery.schema.json"><code>../schemas/host-discovery-v1.schema.json</code></a>, discovery;</li><li><a href="/schemas/v1/form-ref.schema.json"><code>../schemas/form-ref-v1.schema.json</code></a>, exact Form identity;</li><li><a href="/schemas/v1/host-api-wire.schema.json"><code>../schemas/host-api-wire-v1.schema.json</code></a>, resource and error envelopes;</li><li><a href="/schemas/operations/v1/operation.schema.json"><code>../schemas/operation-v1.schema.json</code></a>, long-running operation records; and</li><li><a href="/schemas/support/v1/host-support-profile.schema.json"><code>../schemas/host-support-profile-v1.schema.json</code></a>, Host support answers.</li></ul><h2 id="discovery-and-routing" tabindex="-1">Discovery and routing <a class="header-anchor" href="#discovery-and-routing" aria-label="Permalink to &quot;Discovery and routing&quot;">​</a></h2><p><code>GET /.well-known/takoform/v1</code> returns exactly one advertised API lane, <code>forms.takoform.com/v1</code>, with API root <code>/apis/forms.takoform.com/v1</code>. <code>service_forms</code>, <code>exact_form_ref</code>, <code>optimistic_concurrency</code>, <code>idempotent_lifecycle</code>, <code>operations</code>, <code>artifact_upload</code>, and <code>support_profiles</code> are required and true.</p><p>An advertised endpoint is same-origin with the discovery document. Its escaped path contains no percent-encoding, userinfo, query, or fragment. Plain HTTP is valid only for a loopback development origin.</p><p>A stable Form Family group is a versionless reverse-DNS name and travels as one ordinary path segment. A group containing <code>/</code> is invalid. The stable routes therefore use <code>{formGroup}/{kind}</code>, never a separate family-version segment.</p><p>The lifecycle root is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{api}/resources/{formGroup}/{kind}/{name}</span></span></code></pre></div><p>The <code>forms</code>, <code>form-definitions</code>, resource, and Form support routes accept or return the complete exact FormRef. No route accepts <code>latest</code>, an omitted definition version, a group-and-kind alias, or a best available definition. Failure to resolve all four FormRef members is <code>form_unknown</code> before mutation.</p><h2 id="exact-formref" tabindex="-1">Exact FormRef <a class="header-anchor" href="#exact-formref" aria-label="Permalink to &quot;Exact FormRef&quot;">​</a></h2><p>A FormRef is exactly:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;edge.forms.takoform.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WorkerVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;definitionVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.3.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaDigest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sha256:&lt;64 lowercase hexadecimal characters&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>apiVersion</code> is the versionless family group. <code>definitionVersion</code> versions the one Form independently. <code>schemaDigest</code> is the RFC 8785 digest of the immutable Definition. All four members participate in equality, catalog lookup, stored identity, relation pins, idempotency fingerprints, and support answers. <code>packageDigest</code> may accompany a FormRef as audit evidence and never participates in any of those decisions.</p><h2 id="wire-and-identity-rules" tabindex="-1">Wire and identity rules <a class="header-anchor" href="#wire-and-identity-rules" aria-label="Permalink to &quot;Wire and identity rules&quot;">​</a></h2><p>Every request and response is UTF-8 I-JSON. A Host validates the raw document before typed decoding. Invalid UTF-8, duplicate members, a non-I-JSON number, trailing data, excessive nesting, or an unknown closed-envelope field is <code>invalid_argument</code> before mutation.</p><p><code>metadata.name</code> is a lowercase DNS-like resource name. <code>metadata.space</code> is an opaque, case-sensitive SpaceID. A SpaceID is 1 through 255 Unicode code points, has no leading or trailing Unicode whitespace, and contains no slash or control character. Hosts preserve it without trimming, normalization, or case folding.</p><p>Resource identity has three independent Host-issued counters:</p><ul><li><code>uid</code> is immutable for one incarnation. Delete and recreate changes it.</li><li><code>generation</code> starts at <code>1</code> and advances only when portable desired state changes.</li><li><code>revision</code> starts at <code>1</code> and advances on every representation change, including Host-observed status or output changes.</li></ul><p>Generation and revision are canonical positive decimal strings in the signed 64-bit range. A response ETag is exactly one strong quoted revision.</p><p>Every response echoes the exact FormRef recorded at creation or import. A request under another definition never reinterprets stored state and never causes a catalog fallback.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>The stable lifecycle capabilities are <code>create</code>, <code>read</code>, <code>update</code>, <code>delete</code>, <code>import</code>, and <code>observe</code>. A Definition declares the subset it supports. A Host may narrow its own support profile and must never widen the Definition.</p><p><code>validate</code> checks the submitted document and may resolve tenant-scoped UID relations only when the exact Definition declares a resolved-UID constraint; it never decides tenant-specific standard-service satisfiability. <code>prepare</code> materializes portable defaults, validates the exact installed Definition, resolves relations and Host capabilities for the authenticated tenant, and returns a review binding. <code>apply</code> consumes that binding and repeats every mutable-state decision atomically with its write. <code>import</code> performs the same semantic validation before adopting a native identity. <code>observe</code> refreshes Host-observed state without changing desired state. <code>delete</code> removes only the addressed incarnation.</p><p>Create requires <code>If-None-Match: *</code>. Update, observe, prepare of an existing resource, and delete require <code>Takoform-Expected-Generation</code> or the equivalent body field where the operation table permits it. If both transports are sent they are equal. <code>If-Match</code>, when sent, carries the exact strong revision ETag. An absent required fence is <code>invalid_argument</code>; a stale generation is <code>generation_conflict</code>; a stale revision is <code>revision_conflict</code>; and an expected UID naming another incarnation is <code>uid_mismatch</code>.</p><p>Every mutation requires an idempotency key scoped by authenticated tenant, principal, operation, resource address, and exact request fingerprint. Reusing the key with another fingerprint is <code>invalid_argument</code>. A recorded answer does not outlive the incarnation or operation it reports.</p><p>Prepare binds the canonical materialized spec digest, exact FormRef, resource address, current UID and generation (or the create markers), and Host plan. Substitution is <code>invalid_argument</code> before mutation. An accepted asynchronous mutation repeats relation, constraint, claim, capability, artifact, and standard-service checks at commit.</p><h2 id="relations-and-bindings" tabindex="-1">Relations and bindings <a class="header-anchor" href="#relations-and-bindings" aria-label="Permalink to &quot;Relations and bindings&quot;">​</a></h2><p>References are closed <code>{apiVersion, kind, name}</code> objects derived from the installed Definition&#39;s desired schema. The source resource&#39;s authenticated tenant and <code>metadata.space</code> supply scope; cross-space and cross-tenant lookup is unrepresentable. A missing target is <code>resource_not_found</code> before mutation.</p><p>Resolution records the relation pointer, target address, target UID, and target exact FormRef. A target replacement does not retarget the source: it renders the source not Ready until the source is reapplied and deliberately repinned. Deleting a live target with dependents is <code>dependency_in_use</code>.</p><p>A typed binding additionally resolves its exact Binding Definition, source role, allowed target FormRefs, and required Interface. A missing contract is <code>unsupported_capability</code>; a contract mismatch is <code>invalid_argument</code>. No Host may infer a binding from names or from a target that merely looks compatible.</p><h2 id="declared-constraints" tabindex="-1">Declared constraints <a class="header-anchor" href="#declared-constraints" aria-label="Permalink to &quot;Declared constraints&quot;">​</a></h2><p>A stable Form Definition carries a closed top-level <code>constraints</code> array. A Host that does not implement a declared kind refuses installation with <code>unsupported_capability</code>. Constraints are checked at validate or prepare as applicable, on synchronous apply and import, and again inside an asynchronous commit. No declared constraint may be parsed and ignored.</p><p>The stable constraint kinds are:</p><ul><li><code>exclusive</code>: at most one live resource of the exact source Form may hold the referenced target UID, optionally keyed by another desired value.</li><li><code>sum</code>: integer members of the declared list total exactly the declared value.</li><li><code>claim</code>: one canonical desired value has at most one live claimant per tenant, across spaces.</li><li><code>hostAssigned</code>: the Host mints the declared output, keeps it stable for the UID, and accepts no desired-state substitute.</li><li><code>orderedPair</code>: the concrete numeric value at the first pointer is less than or equal to the value at the second pointer.</li><li><code>uniqueBy</code>: every object in the declared list has a distinct canonical scalar value for the declared member. Equivalent JSON number spellings compare equal; strings and numbers remain different domains.</li><li><code>acyclic</code>: following the declared relation through live UID-pinned resources never reaches the source UID and never forms a cycle. Traversal is bounded; an unreadable or replaced edge fails closed.</li><li><code>distinctPair</code>: when both optional relations are present, they resolve to two different immutable UIDs.</li><li><code>uniquePair</code>: the ordered pair of resolved UIDs is held by at most one live resource per tenant and exact FormRef. Reverse order is a different pair.</li><li><code>sameResolvedTarget</code>: the anchor relation and every relation reached through the declared member list and member pointer resolve to the same immutable UID.</li></ul><p>Checks and writes for <code>exclusive</code>, <code>claim</code>, and <code>uniquePair</code> are serializable or use an equivalent atomic reservation. A prepare-only implementation is not conforming because two prepared requests could otherwise both commit.</p><h2 id="standard-services" tabindex="-1">Standard services <a class="header-anchor" href="#standard-services" aria-label="Permalink to &quot;Standard services&quot;">​</a></h2><p>A desired-schema property annotated <code>x-takoform-standard-services: standards.takoform.com/v1</code> contains sealed <code>{name, service, required?}</code> slots. <code>required</code> defaults to true. <code>service</code> is an exact stable StandardServiceRef:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;apiVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;standards.takoform.com/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.amazonaws.s3&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>protocol</code> is an opaque normalized reverse-DNS identifier with at least three labels and at most 253 characters. Takoform defines no central protocol enum. Syntax validity does not claim protocol conformance and does not imply Host support.</p><p>Support is Host- and tenant-specific:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET {api}/support/standard-services/{protocol}</span></span></code></pre></div><p>The response is <code>support.takoform.com/v1</code>, kind <code>StandardServiceSupport</code>, echoes the exact stable StandardServiceRef, and carries a boolean <code>satisfiable</code>. A grammar-valid unknown identifier receives a 200 profile with <code>satisfiable: false</code>; it is not a missing Takoform registry entry.</p><p>The reference Host&#39;s structured object-storage protocol is <code>com.amazonaws.s3</code>. A required unsupported slot is <code>unsupported_capability</code> at prepare and again before any direct or asynchronous mutation. An optional unsupported slot blocks nothing and projects nothing. Resolved endpoints, credentials, secrets, passwords, and vendor configuration never appear in desired state, observed state, outputs, diagnostics, provider state, or support profiles.</p><h2 id="artifacts-and-operations" tabindex="-1">Artifacts and operations <a class="header-anchor" href="#artifacts-and-operations" aria-label="Permalink to &quot;Artifacts and operations&quot;">​</a></h2><p>Artifact manifests and blobs are content addressed. A digest identifies bytes, not authority. The authenticated tenant must already hold every referenced manifest and blob. A foreign or unknown digest is indistinguishable and fails as <code>artifact_missing</code>. Commit revalidates the manifest kind, declared size, entry count, content digests, and every Form-specific artifact rule.</p><p>A mutation returning HTTP 202 returns an Operation handle bound to the creating tenant and principal. A foreign caller receives <code>operation_not_found</code>, not a confirmation that the handle exists. Pending Operations carry neither result nor error. A terminal Operation carries exactly one. Terminal errors require a request ID and <code>retryable: false</code>; starting a new operation is a caller choice, not a continuation of a completed record.</p><h2 id="conditions-outputs-and-errors" tabindex="-1">Conditions, outputs, and errors <a class="header-anchor" href="#conditions-outputs-and-errors" aria-label="Permalink to &quot;Conditions, outputs, and errors&quot;">​</a></h2><p>The portable condition types are <code>Ready</code>, <code>Reconciling</code>, <code>Degraded</code>, <code>Drifted</code>, <code>Blocked</code>, and <code>Deleting</code>. Portable reasons are <code>Available</code>, <code>Provisioning</code>, <code>ExternalChange</code>, <code>DependencyMissing</code>, and <code>UnsupportedCapability</code>, only in the type/reason combinations defined by the wire schema. Host-specific detail is optional and never required for portable interpretation.</p><p>Outputs are present exactly when the installed Definition declares an <code>outputSchema</code>, validate against that exact schema, and contain no undeclared member. Host-observed details not declared as portable outputs remain outside the resource representation.</p><p>The closed error codes are <code>invalid_argument</code>, <code>unauthenticated</code>, <code>permission_denied</code>, <code>form_unknown</code>, <code>form_not_installed</code>, <code>form_unavailable</code>, <code>resource_not_found</code>, <code>resource_busy</code>, <code>import_conflict</code>, <code>policy_denied</code>, <code>backend_unavailable</code>, <code>internal_error</code>, <code>rate_limited</code>, <code>deadline_exceeded</code>, <code>operation_cancelled</code>, <code>operation_not_found</code>, <code>dependency_in_use</code>, <code>artifact_missing</code>, <code>artifact_invalid</code>, <code>unsupported_capability</code>, <code>migration_required</code>, <code>uid_mismatch</code>, <code>revision_conflict</code>, and <code>generation_conflict</code>. HTTP status and automatic retryability are fixed by <a href="operations-v1.json"><code>operations-v1.json</code></a>. An implementation never adds a new portable code or reason under this lane.</p><h2 id="conformance" tabindex="-1">Conformance <a class="header-anchor" href="#conformance" aria-label="Permalink to &quot;Conformance&quot;">​</a></h2><p>The canonical stable suite is <a href="../../conformance/takoform-v1/manifest.json"><code>../../conformance/takoform-v1/manifest.json</code></a>. It contains a concrete generic Host corpus, one semantic corpus for every family in <code>forms/candidates/current-family-index.json</code>, and an all-family composition corpus. The manifest owns the shell-free reference runner command, corpus digests, ordered check lists, and exact runner FormRefs.</p><p>The generic corpus executes the complete lifecycle, fencing, relation, artifact, operation, declared-constraint, and stable standard-service matrix. Each family corpus validates and drives every current candidate exactly once. The composition corpus resolves all current families together and proves that a wrong digest is refused rather than substituted. Retained beta corpora are historical artifacts and are not rewritten by the stable derivation.</p>`,55)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
